installation.script:
#!/bin/bash
set -euo pipefail
apt-get update -qq
DEBIAN_FRONTEND=noninteractive apt-get install -y -qq ca-certificates curl tar python3
curl -fsSL --retry 3 https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /mnt/server/wp-cli.phar
chmod 0644 /mnt/server/wp-cli.phar
mkdir -p /mnt/server/www /mnt/server/logs
# Copy required upstream Nginx/PHP runtime files into the Pterodactyl server volume.
apt-get install -y -qq git
mkdir -p /mnt/server/nginx /mnt/server/php /mnt/server/modules
if [ ! -x /mnt/server/start-modules.sh ] || [ ! -x /mnt/server/modules/nginx/start.sh ]; then
  tmp_upstream="$(mktemp -d)"
  git clone --depth 1 https://github.com/Ym0T/pterodactyl-nginx-egg.git "$tmp_upstream/upstream"
  cp -rn "$tmp_upstream/upstream/nginx/." /mnt/server/nginx/ 2>/dev/null || true
  cp -rn "$tmp_upstream/upstream/php/." /mnt/server/php/ 2>/dev/null || true
  cp -rn "$tmp_upstream/upstream/modules/." /mnt/server/modules/ 2>/dev/null || true
  cp "$tmp_upstream/upstream/start-modules.sh" /mnt/server/start-modules.sh
  chmod +x /mnt/server/start-modules.sh /mnt/server/modules/*/start.sh 2>/dev/null || true
  rm -rf "$tmp_upstream"
fi
cd /mnt/server/www
if [ ! -f wp-includes/version.php ]; then
  if [ -z "$(ls -A . 2>/dev/null || true)" ]; then
    echo "[WordPress] Downloading latest WordPress..."
    curl -fsSL --retry 3 https://wordpress.org/latest.tar.gz -o /tmp/wordpress.tar.gz
    tar -xzf /tmp/wordpress.tar.gz --strip-components=1 -C /mnt/server/www
    rm -f /tmp/wordpress.tar.gz
  else
    echo "[WordPress] www/ is not empty and WordPress core is missing; leaving files untouched."
  fi
else
  echo "[WordPress] Existing WordPress detected; leaving it untouched."
fi
cat > /mnt/server/configure-wordpress.php <<'PHP'
<?php
$root = '/home/container/www';
$sample = $root . '/wp-config-sample.php';
$config = $root . '/wp-config.php';
$dbName = getenv('WP_DB_NAME') ?: '';
$dbUser = getenv('WP_DB_USER') ?: '';
$dbPass = getenv('WP_DB_PASSWORD') ?: '';
$dbHost = getenv('WP_DB_HOST') ?: '';
$dbPrefix = trim(getenv('WP_DB_PREFIX') ?: 'wp_');
if ($dbPrefix === '' || !preg_match('/^[A-Za-z0-9_]+$/', $dbPrefix)) { echo "[WordPress] Invalid WP_DB_PREFIX; use only letters, numbers, and underscores. Falling back to wp_.\n"; $dbPrefix = 'wp_'; }
$domain = trim(getenv('WP_DOMAIN') ?: '');
$scheme = strtolower(trim(getenv('WP_SCHEME') ?: 'https'));
if (!in_array($scheme, ['http', 'https'], true)) { $scheme = 'https'; }
if (!file_exists($config)) {
  if (!file_exists($sample)) { echo "[WordPress] WordPress sample config not found; skipping DB config.\n"; exit(0); }
  if ($dbName === '' || $dbUser === '' || $dbHost === '') { echo "[WordPress] DB variables incomplete; configure wp-config.php manually or fill WP_DB_* variables.\n"; exit(0); }
  $s = file_get_contents($sample);
  $replacements = [
    "define( 'DB_NAME', 'database_name_here' );" => "define( 'DB_NAME', " . var_export($dbName, true) . " );",
    "define( 'DB_USER', 'username_here' );" => "define( 'DB_USER', " . var_export($dbUser, true) . " );",
    "define( 'DB_PASSWORD', 'password_here' );" => "define( 'DB_PASSWORD', " . var_export($dbPass, true) . " );",
    "define( 'DB_HOST', 'localhost' );" => "define( 'DB_HOST', " . var_export($dbHost, true) . " );",
  ];
  $s = str_replace(array_keys($replacements), array_values($replacements), $s);
  // Apply the configurable MySQL/MariaDB table prefix to a newly generated wp-config.php.
  $s = str_replace('$table_prefix = \'wp_\';', '$table_prefix = ' . var_export($dbPrefix, true) . ';', $s);
  foreach (['AUTH_KEY','SECURE_AUTH_KEY','LOGGED_IN_KEY','NONCE_KEY','AUTH_SALT','SECURE_AUTH_SALT','LOGGED_IN_SALT','NONCE_SALT'] as $key) {
    $salt = bin2hex(random_bytes(48));
    $s = preg_replace("/define\\(\\s*'" . preg_quote($key, '/') . "'\\s*,\\s*'put your unique phrase here'\\s*\\);/", "define( '" . $key . "', '" . $salt . "' );", $s);
  }
  // Keep the sample's existing WP_DEBUG definition; do not add a duplicate constant.
  $s = preg_replace("/define\\(\\s*'WP_DEBUG'\\s*,.*?\\);/s", "define( 'WP_DEBUG', " . (filter_var(getenv('WP_DEBUG') ?: '0', FILTER_VALIDATE_BOOLEAN) ? 'true' : 'false') . " );", $s, 1);
  $s = str_replace("/* That's all, stop editing! Happy publishing. */", "define( 'WP_DEBUG_LOG', false );\ndefine( 'WP_DEBUG_DISPLAY', false );\n/* That's all, stop editing! Happy publishing. */", $s);
  if (file_put_contents($config, $s, LOCK_EX) === false) { fwrite(STDERR, "[WordPress] Could not write wp-config.php\n"); exit(1); }
  @chmod($config, 0640);
  echo "[WordPress] wp-config.php created from WP_DB_* settings.\n";
}
// Apply domain constants on every start so WP_DOMAIN changes take effect without overwriting wp-config.php.
if (file_exists($config) && $domain !== '') {
  $url = $scheme . '://' . preg_replace('~^https?://~i', '', rtrim($domain, '/'));
  $contents = file_get_contents($config);
  $contents = preg_replace("/^\\s*define\\(\\s*'WP_HOME'\\s*,.*?\\);\\s*\\n?/m", '', $contents);
  $contents = preg_replace("/^\\s*define\\(\\s*'WP_SITEURL'\\s*,.*?\\);\\s*\\n?/m", '', $contents);
  $constants = "define( 'WP_HOME', " . var_export($url, true) . " );\ndefine( 'WP_SITEURL', " . var_export($url, true) . " );\n";
  if (strpos($contents, "/* That's all, stop editing! Happy publishing. */") !== false) {
    $contents = str_replace("/* That's all, stop editing! Happy publishing. */", $constants . "/* That's all, stop editing! Happy publishing. */", $contents);
  } else {
    $contents = preg_replace('/<\\?php\\s*/', "<?php\n" . $constants, $contents, 1);
  }
  if (file_put_contents($config, $contents, LOCK_EX) === false) { fwrite(STDERR, "[WordPress] Could not apply WP_DOMAIN.\n"); exit(1); }
  echo "[WordPress] Domain configured as " . $url . "\n";
}
// Normalize legacy configs on every start: remove literal "\\n" lines and keep one WP_DEBUG definition.
if (file_exists($config)) {
  $contents = file_get_contents($config);
  $before = $contents;
  // Remove only a standalone literal backslash+n line; never strip \n inside strings or other settings.
  $lines = preg_split('/(?<=\\n)/', $contents);
  $kept = [];
  foreach ($lines as $line) {
    if (trim($line) === '\\n') continue;
    $kept[] = $line;
  }
  $contents = implode('', $kept);
  $debug = filter_var(getenv('WP_DEBUG') ?: '0', FILTER_VALIDATE_BOOLEAN) ? 'true' : 'false';
  $contents = preg_replace("/^[ \\t]*define\\(\\s*'WP_DEBUG'\\s*,.*?\\);[ \\t]*\\r?\\n?/m", '', $contents);
  $debugLine = "define( 'WP_DEBUG', " . $debug . " );" . PHP_EOL;
  $marker = "/* That's all, stop editing! Happy publishing. */";
  if (strpos($contents, $marker) !== false) $contents = str_replace($marker, $debugLine . $marker, $contents);
  else $contents = preg_replace('/<\\?php\\s*/', "<?php" . PHP_EOL . $debugLine, $contents, 1);
  if ($contents !== $before && file_put_contents($config, $contents, LOCK_EX) === false) { fwrite(STDERR, "[WordPress] Could not normalize wp-config.php.\\n"); exit(1); }
  // Fail clearly before PHP-FPM starts if config is still invalid.
  exec('php -l ' . escapeshellarg($config) . ' 2>&1', $lint, $lintCode);
  if ($lintCode !== 0) { fwrite(STDERR, "[WordPress] wp-config.php syntax check failed:\\n" . implode("\\n", $lint) . "\\n"); exit(1); }
  echo "[WordPress] wp-config.php syntax validated.\\n";
}
PHP
cat > /mnt/server/install-wordpress-core.php <<'PHP'
<?php
$root = '/home/container/www';
$user = trim(getenv('WP_ADMIN_USER') ?: '');
$pass = getenv('WP_ADMIN_PASSWORD') ?: '';
$email = trim(getenv('WP_ADMIN_EMAIL') ?: '');
if (!is_file($root . '/wp-config.php') || !is_file($root . '/wp-includes/version.php')) {
  echo "[WordPress] Core/config not ready; first-install step deferred.\n"; exit(0);
}
if ($user === '' || $pass === '' || $email === '') {
  echo "[WordPress] First install needs WP_ADMIN_USER, WP_ADMIN_PASSWORD and WP_ADMIN_EMAIL; existing sites are left untouched.\n"; exit(0);
}
if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
  echo "[WordPress] WP_ADMIN_EMAIL is invalid; automatic install deferred.\n"; exit(0);
}
function wpCli($args) {
  exec('php ' . escapeshellarg('/home/container/wp-cli.phar') . ' --path=' . escapeshellarg('/home/container/www') . ' --allow-root ' . $args . ' 2>&1', $out, $code);
  return [$code, implode("\n", $out)];
}
[$installedCode] = wpCli('core is-installed');
if ($installedCode === 0) { echo "[WordPress] Existing installation detected; leaving it untouched.\n"; exit(0); }
$dbCode = 1; $lastError = '';
$dbHostRaw = trim(getenv('WP_DB_HOST') ?: '');
$dbName = getenv('WP_DB_NAME') ?: '';
$dbUser = getenv('WP_DB_USER') ?: '';
$dbPass = getenv('WP_DB_PASSWORD') ?: '';
$dbHost = $dbHostRaw; $dbPort = 3306;
if (preg_match('/^(.+):([0-9]+)$/', $dbHostRaw, $hostMatch)) { $dbHost = $hostMatch[1]; $dbPort = (int)$hostMatch[2]; }
for ($attempt = 1; $attempt <= 10; $attempt++) {
  if (!function_exists('mysqli_init')) { $lastError = 'PHP mysqli extension is missing.'; break; }
  $conn = mysqli_init();
  mysqli_options($conn, MYSQLI_OPT_CONNECT_TIMEOUT, 4);
  if (@mysqli_real_connect($conn, $dbHost, $dbUser, $dbPass, $dbName, $dbPort)) { $dbCode = 0; mysqli_close($conn); break; }
  $lastError = mysqli_connect_error() ?: 'Unknown MySQL connection error';
  echo "[WordPress] Waiting for database (attempt {$attempt}/10)...\n";
  sleep(3);
}
if ($dbCode !== 0) { echo "[WordPress] Database not ready/reachable; install deferred. " . substr($lastError, 0, 300) . "\n"; exit(0); }
$domain = preg_replace('~^https?://~i', '', rtrim(trim(getenv('WP_DOMAIN') ?: ''), '/'));
if ($domain === '') { echo "[WordPress] WP_DOMAIN is empty; automatic install deferred.\n"; exit(0); }
$scheme = strtolower(trim(getenv('WP_SCHEME') ?: 'https'));
if (!in_array($scheme, ['http','https'], true)) $scheme = 'https';
$title = trim(getenv('WP_SITE_TITLE') ?: 'WordPress');
$args = 'core install --url=' . escapeshellarg($scheme . '://' . $domain) .
  ' --title=' . escapeshellarg($title) . ' --admin_user=' . escapeshellarg($user) .
  ' --admin_password=' . escapeshellarg($pass) . ' --admin_email=' . escapeshellarg($email) . ' --skip-email';
[$code, $out] = wpCli($args);
if ($code === 0) echo "[WordPress] First installation completed successfully.\n";
else echo "[WordPress] Automatic install failed; check DB settings and WP_ADMIN_* variables. " . substr($out, 0, 500) . "\n";
PHP
chmod 0644 /mnt/server/install-wordpress-core.php

cat > /mnt/server/npm-auto-proxy.php <<'PHP'
<?php
// Optional Nginx Proxy Manager integration. Credentials must belong to a dedicated NPM account.
$enabled = filter_var(getenv('NPM_AUTO_SETUP') ?: '1', FILTER_VALIDATE_BOOLEAN);
$domainInput = trim(getenv('WP_DOMAIN') ?: '');
$domain = preg_replace('~^https?://~i', '', rtrim($domainInput, '/'));
if (!$enabled || $domain === '') { exit(0); }
if (strpos($domain, '/') !== false || strpos($domain, ' ') !== false || !preg_match('/^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)(?:\\.(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?))+$/', $domain)) {
  echo "[NPM] WP_DOMAIN must be a hostname such as example.com; skipping automatic proxy setup.\\n"; exit(0);
}
$base = rtrim(trim(getenv('NPM_URL') ?: ''), '/');
if ($base !== '' && !preg_match('~^https?://~i', $base)) { echo "[NPM] NPM_URL must start with http:// or https://; skipping automatic proxy setup.\\n"; exit(0); }
$email = trim(getenv('NPM_EMAIL') ?: '');
$password = getenv('NPM_PASSWORD') ?: '';
$leEmail = trim(getenv('NPM_LE_EMAIL') ?: $email);
$forwardHost = trim(getenv('NPM_FORWARD_HOST') ?: '');
$forwardPort = (int)(getenv('NPM_FORWARD_PORT') ?: (getenv('SERVER_PORT') ?: 0));
if (!$base || !$email || !$password || !$leEmail || !$forwardHost || $forwardPort < 1 || $forwardPort > 65535) {
  echo "[NPM] Auto setup enabled but NPM_URL, NPM_EMAIL, NPM_PASSWORD, NPM_FORWARD_HOST and NPM_FORWARD_PORT (or SERVER_PORT) must be configured.\n"; exit(0);
}
if (!function_exists('curl_init')) { echo "[NPM] PHP cURL extension is missing; skipping automatic proxy setup.\n"; exit(0); }
function npmRequest($method, $url, $token = '', $payload = null) {
  $ch = curl_init($url);
  $headers = ['Accept: application/json', 'Content-Type: application/json'];
  if ($token !== '') $headers[] = 'Authorization: Bearer ' . $token;
  curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_CUSTOMREQUEST=>$method, CURLOPT_HTTPHEADER=>$headers, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_TIMEOUT=>180]);
  if ($payload !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($payload, JSON_UNESCAPED_SLASHES));
  $body = curl_exec($ch); $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE); $err = curl_error($ch); curl_close($ch);
  if ($body === false) throw new RuntimeException('Request failed: ' . $err);
  $json = json_decode($body, true);
  if ($code < 200 || $code >= 300) {
    $msg = is_array($json) ? ($json['error']['message'] ?? $json['message'] ?? '') : '';
    throw new RuntimeException('NPM API returned HTTP ' . $code . ($msg ? ': ' . $msg : ''));
  }
  return $json;
}
try {
  $auth = npmRequest('POST', $base . '/api/tokens', '', ['identity'=>$email, 'secret'=>$password]);
  $token = $auth['token'] ?? '';
  if (!$token) throw new RuntimeException('NPM did not return an API token.');
  $domains = npmRequest('GET', $base . '/api/nginx/proxy-hosts', $token);
  $host = null;
  foreach (($domains ?? []) as $item) { if (in_array($domain, $item['domain_names'] ?? [], true)) { $host = $item; break; } }
  $certs = npmRequest('GET', $base . '/api/nginx/certificates', $token);
  $certId = 0;
  foreach (($certs ?? []) as $cert) { if (($cert['provider'] ?? '') === 'letsencrypt' && in_array($domain, $cert['domain_names'] ?? [], true)) { $certId = (int)$cert['id']; break; } }
  if (!$certId) {
    echo "[NPM] Requesting Let's Encrypt certificate for {$domain}...\n";
    $cert = npmRequest('POST', $base . '/api/nginx/certificates', $token, ['provider'=>'letsencrypt', 'nice_name'=>$domain, 'domain_names'=>[$domain], 'meta'=>['dns_challenge'=>false]]);
    $certId = (int)($cert['id'] ?? 0);
    if (!$certId) throw new RuntimeException('Certificate request returned no certificate ID.');
  } else { echo "[NPM] Reusing existing Let's Encrypt certificate for {$domain}.\n"; }
  $payload = [
    'domain_names'=>[$domain], 'forward_scheme'=>'http', 'forward_host'=>$forwardHost, 'forward_port'=>$forwardPort,
    'certificate_id'=>$certId, 'ssl_forced'=>true, 'caching_enabled'=>false, 'block_exploits'=>true,
    'advanced_config'=>'', 'allow_websocket_upgrade'=>true,
    'http2_support'=>true, 'hsts_enabled'=>true, 'hsts_subdomains'=>false, 'locations'=>[], 'enabled'=>true, 'access_list_id'=>0
  ];
  if ($host) {
    // Avoid clobbering unrelated settings; this integration owns the matching domain's host config.
    $result = npmRequest('PUT', $base . '/api/nginx/proxy-hosts/' . (int)$host['id'], $token, $payload);
    echo "[NPM] Updated proxy host and forced HTTPS for {$domain}.\n";
  } else {
    $result = npmRequest('POST', $base . '/api/nginx/proxy-hosts', $token, $payload);
    echo "[NPM] Created proxy host with HTTPS for {$domain}.\n";
  }
} catch (Throwable $e) {
  // Do not print URLs, tokens, or passwords.
  echo "[NPM] Automatic setup failed: " . $e->getMessage() . "\n";
  echo "[NPM] Check API access, DNS, public inbound ports 80/443, and the forwarding host/port.\n";
}
PHP
cat > /mnt/server/start-wordpress.sh <<'SH'
#!/usr/bin/env bash
set -Eeuo pipefail
cd /home/container

# Repair missing upstream runtime scripts on existing servers, without overwriting custom files.
if [ ! -x /home/container/start-modules.sh ] || [ ! -x /home/container/modules/nginx/start.sh ]; then
  echo "[Startup] Missing upstream module files; restoring missing files..."
  tmp="$(mktemp -d)"
  if curl -fsSL --retry 3 https://github.com/Ym0T/pterodactyl-nginx-egg/archive/refs/heads/main.tar.gz -o "$tmp/upstream.tar.gz" &&
     tar -xzf "$tmp/upstream.tar.gz" -C "$tmp"; then
    src="$(find "$tmp" -maxdepth 1 -type d -name 'pterodactyl-nginx-egg-*' | head -n1)"
    if [ -n "$src" ]; then
      mkdir -p /home/container/modules /home/container/nginx /home/container/php
      cp -rn "$src/modules/." /home/container/modules/ 2>/dev/null || true
      cp -rn "$src/nginx/." /home/container/nginx/ 2>/dev/null || true
      cp -rn "$src/php/." /home/container/php/ 2>/dev/null || true
      [ -f /home/container/start-modules.sh ] || cp "$src/start-modules.sh" /home/container/start-modules.sh
      chmod +x /home/container/start-modules.sh /home/container/modules/*/start.sh 2>/dev/null || true
    fi
  fi
  rm -rf "$tmp"
  if [ ! -x /home/container/start-modules.sh ] || [ ! -x /home/container/modules/nginx/start.sh ]; then
    echo "[Startup] ERROR: Cannot restore the Nginx module runner. Check outbound HTTPS or reinstall the Egg."
    exit 1
  fi
fi

php /home/container/configure-wordpress.php || echo "[WordPress] Configuration step failed; check WP_DB_* and WP_DOMAIN settings."
if [ -f /home/container/configure-wordpress-cache.php ]; then
  php /home/container/configure-wordpress-cache.php || true
fi
if [ -f /home/container/install-wordpress-core.php ]; then
  php /home/container/install-wordpress-core.php || echo "[WordPress] First-install step failed; continuing startup."
fi
if [ -f /home/container/setup-wordpress-cache.sh ]; then
  bash /home/container/setup-wordpress-cache.sh || echo "[Cache] Optional cache setup failed; continuing startup."
fi
if [ -f /home/container/npm-auto-proxy.php ]; then
  php /home/container/npm-auto-proxy.php || echo "[NPM] Optional proxy automation failed; continuing startup."
fi
bash /home/container/start-modules.sh &
MODULE_PID=$!
sleep 2
if command -v curl >/dev/null 2>&1; then
  HTTP_CODE="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 5 http://127.0.0.1/ || true)"
  if [[ "$HTTP_CODE" =~ ^[23][0-9][0-9]$ ]]; then
    echo "[Health] Local HTTP check passed (HTTP $HTTP_CODE)."
  else
    echo "[Health] Local HTTP check failed (HTTP ${HTTP_CODE:-no response}); inspect nginx logs and port forwarding."
  fi
fi
wait "$MODULE_PID"
SH
chmod +x /mnt/server/start-wordpress.sh
chmod 0644 /mnt/server/configure-wordpress.php
chown -R 1000:1000 /mnt/server 2>/dev/null || true
cat > /mnt/server/setup-wordpress-cache.sh <<'SH'
#!/bin/bash
set +e
cd /home/container
export HOME="/home/container"
export WP_CLI_CACHE_DIR="/home/container/.wp-cli/cache"
mkdir -p "$WP_CLI_CACHE_DIR" 2>/dev/null || true
WP_PATH="/home/container/www"
WPCLI="/home/container/wp-cli.phar"
if [ ! -f "$WP_PATH/wp-config.php" ] || [ ! -f "$WPCLI" ]; then
  echo "[Cache] WordPress config or WP-CLI missing; cache setup will retry next start."
  exit 0
fi
if ! php "$WPCLI" --path="$WP_PATH" --allow-root core is-installed >/dev/null 2>&1; then
  echo "[Cache] WordPress is not installed yet; skipping plugin setup until the database is ready."
  exit 0
fi
CACHE_ENABLED="${WP_CACHE_ENABLED:-true}"
if [[ "$CACHE_ENABLED" =~ ^(1|true|yes|on)$ ]]; then
  if php "$WPCLI" --path="$WP_PATH" --allow-root plugin is-installed cache-enabler >/dev/null 2>&1; then
    php "$WPCLI" --path="$WP_PATH" --allow-root plugin activate cache-enabler
  else
    php "$WPCLI" --path="$WP_PATH" --allow-root plugin install cache-enabler --activate
  fi
  echo "[Cache] Page cache enabled (Cache Enabler)."
else
  php "$WPCLI" --path="$WP_PATH" --allow-root plugin deactivate cache-enabler >/dev/null 2>&1 || true
  echo "[Cache] Page cache disabled (Cache Enabler deactivated)."
fi
REDIS_ENABLED="${WP_REDIS_ENABLED:-false}"
REDIS_HOST="${WP_REDIS_HOST:-}"
if [[ "$REDIS_ENABLED" =~ ^(1|true|yes|on)$ ]] && [ -n "$REDIS_HOST" ]; then
  if php -m 2>/dev/null | grep -qi "^redis"; then
    if php "$WPCLI" --path="$WP_PATH" --allow-root plugin is-installed redis-cache >/dev/null 2>&1; then
      php "$WPCLI" --path="$WP_PATH" --allow-root plugin activate redis-cache
    else
      php "$WPCLI" --path="$WP_PATH" --allow-root plugin install redis-cache --activate
    fi
    php "$WPCLI" --path="$WP_PATH" --allow-root redis enable
    echo "[Redis] Redis object cache enabled for the configured host."
  else
    echo "[Redis] Enabled and host configured, but PHP ext-redis is missing; skipping Redis connection."
  fi
else
  php "$WPCLI" --path="$WP_PATH" --allow-root plugin deactivate redis-cache >/dev/null 2>&1 || true
  DROPIN="$WP_PATH/wp-content/object-cache.php"
  if [ -f "$DROPIN" ] && grep -Eqi "Redis Object Cache|WP_REDIS_HOST|RedisCache|Redis" "$DROPIN"; then
    mv -n "$DROPIN" "$DROPIN.redis-disabled" 2>/dev/null || true
    echo "[Redis] Redis drop-in disabled; backup kept."
  fi
  echo "[Redis] Disabled or no host configured; skipping Redis setup."
fi
SH
chmod +x /mnt/server/setup-wordpress-cache.sh
cat > /mnt/server/configure-wordpress-cache.php <<'PHP'
<?php
$config = '/home/container/www/wp-config.php';
if (!file_exists($config)) { echo "[Cache] wp-config.php not found; skipping cache constants.\n"; exit(0); }
$enabled = filter_var(getenv('WP_CACHE_ENABLED') ?: '1', FILTER_VALIDATE_BOOLEAN);
$host = trim(getenv('WP_REDIS_HOST') ?: '');
$port = (int)(getenv('WP_REDIS_PORT') ?: 6379);
$password = getenv('WP_REDIS_PASSWORD') ?: '';
$db = (int)(getenv('WP_REDIS_DATABASE') ?: 0);
$prefix = trim(getenv('WP_REDIS_PREFIX') ?: 'wp_');
$redisEnabled = filter_var(getenv('WP_REDIS_ENABLED') ?: '0', FILTER_VALIDATE_BOOLEAN);
$content = file_get_contents($config);
$begin = "/* BENDMEN_CACHE_CONFIG_BEGIN */";
$end = "/* BENDMEN_CACHE_CONFIG_END */";
$pattern = '~\\s*/\\* BENDMEN_CACHE_CONFIG_BEGIN \\*/.*?/\\* BENDMEN_CACHE_CONFIG_END \\*/\\s*~s';
$content = preg_replace($pattern, "\n", $content);
$lines = [$begin, "define( 'WP_CACHE', " . ($enabled ? 'true' : 'false') . " );"];
if ($redisEnabled && $host !== '') {
  $lines[] = "define( 'WP_REDIS_HOST', " . var_export($host, true) . " );";
  $lines[] = "define( 'WP_REDIS_PORT', " . max(1, min(65535, $port)) . " );";
  $lines[] = "define( 'WP_REDIS_DATABASE', " . max(0, min(15, $db)) . " );";
